"use strict";(globalThis.webpackChunklamp_platform=globalThis.webpackChunklamp_platform||[]).push([[8130],{77735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"dashboard-update-auth-phase-1","metadata":{"permalink":"/blog/dashboard-update-auth-phase-1","source":"@site/blog/2026-07-24-dashboard-auth-phase-1.md","title":"Dashboard Update: Sign-In Changes (Phase 1)","description":"This is Phase 1 of the mindLAMP Authentication Upgrade. On Wednesday, July 29, we\'re updating the LAMP Dashboard and JavaScript SDK, a first step ahead of the larger security upgrade coming later this summer.","date":"2026-07-24T00:00:00.000Z","tags":[{"inline":false,"label":"Authentication","permalink":"/blog/tags/authentication","description":"The mindLAMP authentication and API upgrade"},{"inline":false,"label":"Updates","permalink":"/blog/tags/updates","description":"Platform updates and new features"}],"readingTime":1.99,"hasTruncateMarker":true,"authors":[{"name":"Eden Rozenblit","page":{"permalink":"/blog/authors/edenrozenblit"},"socials":{"linkedin":"https://www.linkedin.com/in/eden-rozenblit/","github":"https://github.com/e-rozenblit"},"imageURL":"https://avatars.githubusercontent.com/u/168096182?v=4","key":"edenrozenblit"},{"name":"Matt Flathers","page":{"permalink":"/blog/authors/mattflathers"},"socials":{"linkedin":"https://www.linkedin.com/in/matthew-f-551001141/","github":"https://github.com/MattMatt27"},"imageURL":"https://avatars.githubusercontent.com/u/59424032?v=4","key":"mattflathers"}],"frontMatter":{"slug":"dashboard-update-auth-phase-1","title":"Dashboard Update: Sign-In Changes (Phase 1)","authors":["edenrozenblit","mattflathers"],"tags":["authentication","updates"],"draft":false},"unlisted":false,"nextItem":{"title":"14 New Cognitive Games Arriving July 29","permalink":"/blog/new-cognitive-games"}},"content":"This is **Phase 1** of the [mindLAMP Authentication Upgrade](/blog/authentication-upgrade). On **Wednesday, July 29**, we\'re updating the LAMP Dashboard and JavaScript SDK, a first step ahead of the larger security upgrade coming later this summer.\\n\\n\x3c!-- truncate --\x3e\\n\\n**The changes are fully backward-compatible.** Passive data collection will be unaffected, and no one will be logged out. The one visible change is at sign-in: instead of entering a server address, you\'ll select your server with a button.\\n\\n- **Researchers** will log in as usual, choosing their server with a button.\\n- **Participants** will not be logged out by this update, so nothing changes for them at release. They\'ll see the new server-selection step the next time they sign in for any reason: a new participant on first login, or an existing participant after reinstalling the app, logging out, or signing in on a new device.\\n\\n## Find your setup\\n\\nAt sign-in, you\'ll choose your organization or study from a set of cards:\\n\\n![The mindLAMP sign-in screen: organization cards with a highlighted mindLAMP / BIDMC card and a \\"Connect to a different server\\" option at the bottom](./assets/cards_view.png)\\n\\n### BIDMC-hosted server teams\\n\\n*(You don\'t run your own server, so you typically leave the server address blank when logging in.)*\\n\\nResearchers and first-time participants will connect using the **mindLAMP / BIDMC** button (highlighted above).\\n\\n### Self-hosted teams\\n\\n*(You host your own server and database.)*\\n\\nTeams with a sign-in card will connect by selecting their card. If you don\'t have a card, or would rather not use one, choose **Connect to a different server** and enter your server address manually, as before.\\n\\nWe\'ve contacted the teams that already have a card directly. If you run your own server, did not hear from us, and think you need a card, email mindlamp@bidmc.harvard.edu. To change the name, logo, or host organization on an existing card, let us know by **Tuesday, July 28**.\\n\\n## What\'s next\\n\\nThis is the first step. The core security upgrade rolls out later this summer: session-based authentication, two-factor/OAuth for staff, and API keys for LAMP-py. For the full picture, who\'s affected, and how to prepare, see [The mindLAMP Authentication Upgrade](/blog/authentication-upgrade). We\'ll notify all teams directly before anything changes, so no action is needed now.\\n\\n**Self-hosted teams:** all client updates (dashboard, mobile apps, SDKs) remain compatible with currently released server versions, so no action is required.\\n\\n## Questions?\\n\\nQuestions or problems? Email mindlamp@bidmc.harvard.edu."},{"id":"new-cognitive-games","metadata":{"permalink":"/blog/new-cognitive-games","source":"@site/blog/2026-07-24-new-cognitive-games.md","title":"14 New Cognitive Games Arriving July 29","description":"Fourteen new cognitive assessments have completed development and will be available to teams on the BIDMC-hosted server on Wednesday, July 29. They span attention, working memory, processing speed, executive function, spatial cognition, language, and decision-making, and each produces structured, analysis-ready data.","date":"2026-07-24T00:00:00.000Z","tags":[{"inline":false,"label":"Updates","permalink":"/blog/tags/updates","description":"Platform updates and new features"},{"inline":false,"label":"Announcements","permalink":"/blog/tags/announcements","description":"News and announcements about mindLAMP"}],"readingTime":1.46,"hasTruncateMarker":true,"authors":[{"name":"Eden Rozenblit","page":{"permalink":"/blog/authors/edenrozenblit"},"socials":{"linkedin":"https://www.linkedin.com/in/eden-rozenblit/","github":"https://github.com/e-rozenblit"},"imageURL":"https://avatars.githubusercontent.com/u/168096182?v=4","key":"edenrozenblit"},{"name":"Matt Flathers","page":{"permalink":"/blog/authors/mattflathers"},"socials":{"linkedin":"https://www.linkedin.com/in/matthew-f-551001141/","github":"https://github.com/MattMatt27"},"imageURL":"https://avatars.githubusercontent.com/u/59424032?v=4","key":"mattflathers"}],"frontMatter":{"slug":"new-cognitive-games","title":"14 New Cognitive Games Arriving July 29","authors":["edenrozenblit","mattflathers"],"tags":["updates","announcements"],"draft":false},"unlisted":false,"prevItem":{"title":"Dashboard Update: Sign-In Changes (Phase 1)","permalink":"/blog/dashboard-update-auth-phase-1"},"nextItem":{"title":"The mindLAMP Authentication Upgrade","permalink":"/blog/authentication-upgrade"}},"content":"Fourteen new cognitive assessments have completed development and will be available to teams on the BIDMC-hosted server on **Wednesday, July 29**. They span attention, working memory, processing speed, executive function, spatial cognition, language, and decision-making, and each produces structured, analysis-ready data.\\n\\n\x3c!-- truncate --\x3e\\n\\n**Running your own server?** Email mindlamp@bidmc.harvard.edu and we\'ll walk you through adding them.\\n\\n## The new games\\n\\nEach game links to its full documentation, including scoring and data output.\\n\\n**Processing speed**\\n- **[Simple & Choice Reaction Time](/activities/reference/simple-rt)**: psychomotor processing speed and decision time, combining the two classic Donders reaction-time paradigms.\\n\\n**Attention & cognitive control**\\n- **[Stroop Color-Word Test](/activities/reference/stroop)**: selective attention, cognitive control, and interference suppression (Stroop, 1935).\\n- **[Eriksen Flanker Task](/activities/reference/flanker)**: attentional control and conflict resolution; a core component of the NIH Toolbox Cognition Battery and the Attention Network Test.\\n\\n**Working memory**\\n- **[N-Back](/activities/reference/nback)**: working-memory updating, scored with signal detection theory (d-prime and criterion).\\n- **[Memory Match](/activities/reference/memory-match)**: visual-spatial recognition memory and working memory.\\n\\n**Executive function & planning**\\n- **[Tower of London](/activities/reference/tower-of-london)**: executive function and planning (Shallice, 1982).\\n- **[Wisconsin Card Sorting Test (WCST)](/activities/reference/wcst)**: cognitive flexibility, set-shifting, and abstract reasoning, with perseverative-error scoring.\\n- **[Water Sort](/activities/reference/water-sort)**: planning and problem-solving, in the Tower of London / Tower of Hanoi family.\\n- **[Sliding Puzzle](/activities/reference/sliding-puzzle)**: spatial problem-solving and planning, with move efficiency scored against the mathematically optimal solution.\\n- **[Nonogram](/activities/reference/nonogram)**: logical deduction and constraint satisfaction.\\n\\n**Spatial cognition**\\n- **[Mental Rotation](/activities/reference/mental-rotation)**: spatial visualization ability (Shepard & Metzler, 1971).\\n\\n**Language**\\n- **[Lexical Decision Task](/activities/reference/lexical-decision)**: lexical access speed and word/nonword discrimination (d-prime).\\n- **[Letter Logic](/activities/reference/letter-logic)**: vocabulary, hypothesis testing, and logical deduction (color-coded five-letter word guessing).\\n\\n**Decision-making**\\n- **[Delay Discounting](/activities/reference/delay-discounting)**: temporal impulsivity, quantified with both Area Under the Curve and hyperbolic-k indices.\\n\\n## Documentation\\n\\nBrowse the [full activity reference](/activities/reference) for all games, including the existing suite."},{"id":"authentication-upgrade","metadata":{"permalink":"/blog/authentication-upgrade","source":"@site/blog/2026-07-17-authentication-upgrade.md","title":"The mindLAMP Authentication Upgrade","description":"mindLAMP is rolling out a phased upgrade to how the platform handles authentication, modernizing security for research and clinical teams while keeping disruption to a minimum. This post covers the whole upgrade: the rollout at a glance, then the full detail on what\'s changing, who\'s affected, and how to prepare.","date":"2026-07-17T00:00:00.000Z","tags":[{"inline":false,"label":"Authentication","permalink":"/blog/tags/authentication","description":"The mindLAMP authentication and API upgrade"},{"inline":false,"label":"Announcements","permalink":"/blog/tags/announcements","description":"News and announcements about mindLAMP"}],"readingTime":7.07,"hasTruncateMarker":true,"authors":[{"name":"Eden Rozenblit","page":{"permalink":"/blog/authors/edenrozenblit"},"socials":{"linkedin":"https://www.linkedin.com/in/eden-rozenblit/","github":"https://github.com/e-rozenblit"},"imageURL":"https://avatars.githubusercontent.com/u/168096182?v=4","key":"edenrozenblit"},{"name":"Matt Flathers","page":{"permalink":"/blog/authors/mattflathers"},"socials":{"linkedin":"https://www.linkedin.com/in/matthew-f-551001141/","github":"https://github.com/MattMatt27"},"imageURL":"https://avatars.githubusercontent.com/u/59424032?v=4","key":"mattflathers"}],"frontMatter":{"slug":"authentication-upgrade","title":"The mindLAMP Authentication Upgrade","authors":["edenrozenblit","mattflathers"],"tags":["authentication","announcements"],"draft":false},"unlisted":false,"prevItem":{"title":"14 New Cognitive Games Arriving July 29","permalink":"/blog/new-cognitive-games"},"nextItem":{"title":"Activity Suite Update: Enriched Data Output and Bug Fixes","permalink":"/blog/activity-suite-update-april-2026"}},"content":"mindLAMP is rolling out a phased upgrade to how the platform handles authentication, modernizing security for research and clinical teams while keeping disruption to a minimum. This post covers the whole upgrade: the rollout at a glance, then the full detail on what\'s changing, who\'s affected, and how to prepare.\\n\\n\x3c!-- truncate --\x3e\\n\\n## The rollout at a glance\\n\\n- **Phase 1: Dashboard sign-in (live July 29).** A backward-compatible update to the LAMP Dashboard and JavaScript SDK: you now select your server with a button instead of typing an address. No one is logged out. \u2192 [Dashboard Update: Sign-In Changes (Phase 1)](/blog/dashboard-update-auth-phase-1)\\n- **Later this summer: server authentication, 2FA/OAuth, and API keys.** The core security upgrade, detailed below.\\n\\nWe\'ll notify all teams directly before each change goes live. Some specifics of the later phases may be refined before release; we\'ll confirm final details beforehand.\\n\\n## Why This Update Matters\\n\\nSince its initial release, mindLAMP has used basic authentication, a well-established and widely supported approach where credentials are sent with each API request over an encrypted connection. This model has served the platform reliably and remains secure when paired with TLS encryption, which mindLAMP enforces.\\n\\nThis update moves mindLAMP to a modern session-based authentication model with support for two-factor authentication (2FA) and OAuth. These changes bring mindLAMP in line with current best practices for health data platforms and add meaningful layers of protection for research and clinical environments:\\n\\n- **Session-based authentication** reduces the surface area for credential exposure by eliminating the need to transmit passwords with each request. Sessions are managed server-side with configurable expiration and automatic rotation.\\n- **Two-factor authentication** ensures that access to staff accounts requires both a password and a second verification step, protecting against compromised credentials.\\n- **OAuth support** allows organizations to integrate mindLAMP login with their existing identity providers (e.g. Google), enabling centralized access management and single sign-on.\\n- **API keys** provide a dedicated, auditable mechanism for programmatic access, replacing the use of user credentials in scripts and pipelines.\\n\\nTogether, these changes strengthen mindLAMP\'s security posture across research, clinical, and self-hosted deployments while aligning with the expectations of IRBs, compliance teams, and IT security reviewers.\\n\\n## Timeline\\n\\nThis update is planned for later this summer. We do not have a firm release date yet. **We\'ll publish a follow-up and notify all teams directly before it goes live.**\\n\\n## Who Is Affected\\n\\n| If you are... | Impact level |\\n|---------------|-------------|\\n| A researcher or coordinator using the mindLAMP dashboard | **High**: You will be logged out and required to set up two-factor authentication or OAuth on your next login. |\\n| A participant using the mindLAMP app | **Low**: We\'re working to keep participants unaffected; no logout is expected. |\\n| A developer or data scientist using LAMP-py (Python SDK) | **High**: LAMP-py will require an API key instead of a username and password. |\\n| A team running a self-hosted mindLAMP server | **None**: All client updates (dashboard, mobile apps, SDKs) are backwards compatible with currently released server versions. No action is required at this time. If you installed through LAMP Core and your agreement includes these updates, we\'ll work with you directly. Otherwise, reach out to **mindlamp@bidmc.harvard.edu** to discuss upgrade options. |\\n\\n## What\'s Changing\\n\\n### 1. Server-Side Sessions Replace Basic Authentication\\n\\nThe current mindLAMP server uses basic authentication, where the client sends credentials with each API request over TLS. The updated server introduces server-side sessions: after logging in, the server issues a session token that is used for subsequent requests. Credentials are only transmitted during the initial login.\\n\\n**What this means in practice:**\\n- **Staff will be logged out** when the server is upgraded and will need to log in again. We\'re working to keep participant sessions uninterrupted.\\n- Participant sessions are long-lived and rotate automatically. The app handles this transparently.\\n- Staff sessions expire after a configurable period and require re-login.\\n\\n### 2. Two-Factor Authentication and OAuth for Staff\\n\\nAll staff users (researchers, administrators, coordinators) will be required to add a second layer of security to their accounts. This is a one-time setup that happens on your first login after the update.\\n\\n**First login after the update:**\\n1. Log in with your existing credentials.\\n2. You will be prompted to set up either **two-factor authentication (2FA)** via email, or **OAuth** (sign in with Google, etc.).\\n3. You must complete setup before you can access the dashboard. There is no option to skip.\\n\\n**After setup:**\\n- If you chose 2FA, you\'ll receive a verification code by email each time you log in.\\n- If you chose OAuth, you\'ll sign in through your chosen provider.\\n- Multiple credentials can share the same 2FA email.\\n\\n**If you chose OAuth:** Your credential must have been created with the same email you use for your OAuth provider. If the emails don\'t match, OAuth will not work. Contact your administrator if you need your credential email updated before the release.\\n\\n**Participants are not affected by this requirement.** Two-factor and OAuth are only required for staff accounts.\\n\\n### 3. Account Recovery and Credential Management\\n\\nThe process for managing staff accounts changes after they complete security setup:\\n\\n| Situation | What to do |\\n|-----------|-----------|\\n| Staff user forgets their password | An administrator should **reset their account** via the credential manager (not delete the credential). This removes 2FA/OAuth, generates a temporary password, and logs the user out. |\\n| Staff user loses access to their 2FA email | Same process: administrator resets the account. |\\n| Staff user wants to switch from OAuth to 2FA (or vice versa) | Same process: administrator resets, user reconfigures on next login. |\\n\\n**Important:** If a staff user has a problem with their account, reset it rather than deleting the credential and creating a new one.\\n\\nManaging participant credentials is unchanged. Resetting a participant\'s password will invalidate their sessions and log them out as before.\\n\\n### 4. Credential Changes\\n\\n- **Participant credentials** are now created using usernames (not emails).\\n- **Staff credentials** must be created with email addresses.\\n- You may not have two credentials with the same email address, even across different researchers or if one has been deleted.\\n- Passwords are no longer stored on the credential object.\\n\\n### 5. API Keys Replace Password-Based SDK Access\\n\\nThe current LAMP-py SDK authenticates using a username and password:\\n```python\\nimport LAMP\\nLAMP.connect(\'user@example.com\', \'password\', \'server.example.com\')\\n```\\n\\nThe updated SDK uses API keys for programmatic access:\\n```python\\nimport LAMP\\nLAMP.connect(access_key=\'your-api-key\', server_address=\'server.example.com\')\\n```\\n\\n**How to get an API key:**\\n1. An administrator opens the credential manager in the dashboard.\\n2. Click on the relevant credential and select \\"Manage API Keys.\\"\\n3. Create a new key. **The key value is shown only once**: copy it immediately. If lost, you must generate a new one.\\n\\nAPI key permissions are tied to the credential they are created for.\\n\\n**If you have scripts or pipelines that use `LAMP.connect()` with a username and password, they will need to be updated to use an API key before or shortly after the release.**\\n\\n## How to Prepare\\n\\n**Researchers and coordinators (hosted on our server):**\\n- No action needed right now. When the update goes live, you will be logged out and prompted to set up 2FA or OAuth on your next login.\\n- If you plan to use OAuth, confirm that your credential email matches the email you use for your OAuth provider (Google, etc.). Contact us if you need it updated.\\n\\n**Data scientists and developers using LAMP-py:**\\n- Plan to generate an API key after the update and update your scripts to use it.\\n- Review any automated pipelines that authenticate with username/password; these will stop working after the release.\\n\\n**Self-hosted teams:**\\n- No action is required. All client updates remain compatible with your current server.\\n- If you installed mindLAMP through our LAMP Core team and your agreement includes these security updates, we will work with you directly to plan the upgrade.\\n- If you are running a self-hosted instance and would like to upgrade to take advantage of session-based auth, 2FA, and OAuth, please reach out to **mindlamp@bidmc.harvard.edu** to discuss options through our Core services process.\\n\\n## Questions or Issues?\\n\\nIf you have questions about how these changes affect your study or workflow, or if you encounter any issues after the update, please email **mindlamp@bidmc.harvard.edu**. We\'re happy to help you plan for the transition.\\n\\nWe\'ll publish a follow-up post when the update is live with any final details or changes from what\'s described here."},{"id":"activity-suite-update-april-2026","metadata":{"permalink":"/blog/activity-suite-update-april-2026","source":"@site/blog/2026-04-14-activity-suite-update.md","title":"Activity Suite Update: Enriched Data Output and Bug Fixes","description":"mindLAMP\'s cognitive assessment suite has been updated with enriched data output, bug fixes, and improved mobile responsiveness. All changes to existing games are backward-compatible: existing data fields are preserved and continue to mean the same thing. New fields have been added alongside the old ones to support richer analysis.","date":"2026-04-14T00:00:00.000Z","tags":[{"inline":false,"label":"Updates","permalink":"/blog/tags/updates","description":"Platform updates and new features"},{"inline":false,"label":"Announcements","permalink":"/blog/tags/announcements","description":"News and announcements about mindLAMP"}],"readingTime":4.345,"hasTruncateMarker":true,"authors":[{"name":"Eden Rozenblit","page":{"permalink":"/blog/authors/edenrozenblit"},"socials":{"linkedin":"https://www.linkedin.com/in/eden-rozenblit/","github":"https://github.com/e-rozenblit"},"imageURL":"https://avatars.githubusercontent.com/u/168096182?v=4","key":"edenrozenblit"},{"name":"Matt Flathers","page":{"permalink":"/blog/authors/mattflathers"},"socials":{"linkedin":"https://www.linkedin.com/in/matthew-f-551001141/","github":"https://github.com/MattMatt27"},"imageURL":"https://avatars.githubusercontent.com/u/59424032?v=4","key":"mattflathers"}],"frontMatter":{"slug":"activity-suite-update-april-2026","title":"Activity Suite Update: Enriched Data Output and Bug Fixes","authors":["edenrozenblit","mattflathers"],"tags":["updates","announcements"],"draft":false},"unlisted":false,"prevItem":{"title":"The mindLAMP Authentication Upgrade","permalink":"/blog/authentication-upgrade"},"nextItem":{"title":"Welcome to mindLAMP Updates!","permalink":"/blog/welcome"}},"content":"mindLAMP\'s cognitive assessment suite has been updated with enriched data output, bug fixes, and improved mobile responsiveness. All changes to existing games are **backward-compatible**: existing data fields are preserved and continue to mean the same thing. New fields have been added alongside the old ones to support richer analysis.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What\'s Changed Now\\n\\nThe following changes are live in the current version of mindLAMP.\\n\\n### Enriched Data Output (Additive Only)\\n\\nSeveral existing games now produce additional fields in `static_data` and `temporal_slices`. **All previously existing fields are preserved and unchanged.** If your analysis pipelines already work with these games, they will continue to work without modification. The new fields are available if you want to take advantage of richer data going forward.\\n\\n| Game | New Fields | What You Can Do With Them | Documentation |\\n|------|-----------|--------------------------|---------------|\\n| **Digit Span** | `forward_span`, `backward_span`, `total_raw_score`, `forward_trials_correct`, `backward_trials_correct` | Compute standard WAIS-IV span scores directly. The forward-backward span difference indexes executive contribution to working memory. All legacy fields (`score`, `correct_answers`, `bestForwardDigitSpan`, etc.) are retained and computed the same way. | [Digit Span docs](/activities/reference/digit-span) |\\n| **Spatial Span** | `max_span`, `total_score`, `mode`, `level_results`, `levels_completed`, `starting_span`, `total_levels` | Standard Corsi block-tapping scoring. `max_span` is the primary visuospatial memory measure. `level_results` provides per-trial span, accuracy, and response time for error-pattern analysis. All legacy fields (`correct_answers`, `score`, `StartTime`, `EndTime`, etc.) are retained. | [Spatial Span docs](/activities/reference/spatial-span) |\\n| **Pop the Bubbles** | `levels` array (with `go_correct`, `go_total`, `go_missed`, `nogo_correct`, `nogo_total`, `nogo_wrong`), `score`, `correct_answers`, `wrong_answers` | Compute commission error rate (`nogo_wrong / nogo_total`) for inhibitory control and omission error rate (`go_missed / go_total`) for sustained attention, the core clinical distinction in go/no-go tasks. Previously, go and no-go performance were lumped together. | [Pop the Bubbles docs](/activities/reference/pop-the-bubbles) |\\n| **Spin the Wheel** | `risk_taking_rate`, `net_earnings`, `mean_reaction_time`, `total_high_risk_choices`, `total_low_risk_choices`, `final_balance`, `starting_balance` | `risk_taking_rate` is the primary risk preference measure (0.5 = no preference). Per-spin `temporal_slices` now include `risk_level`, `win_amount`, `loss_amount`, and `balance_after`, enabling analysis of post-outcome risk adjustment. Previously `static_data` was empty. | [Spin the Wheel docs](/activities/reference/spin-the-wheel) |\\n| **Trails B** | `level_summaries` (per-level `duration_ms`, `correct_taps`, `wrong_taps`), `end_reason`, `total_taps`, `total_items` | Per-level completion time (the standard TMT-B metric) and error classification. `end_reason` enables filtering out incomplete administrations. All legacy fields (`correct_answers`, `score`, `percentageCorrectOverall`, etc.) are retained. | [Trails B docs](/activities/reference/trails-b) |\\n\\n**Data collected before this update is not affected.** These changes apply only to new activity completions. Your existing data remains valid and usable.\\n\\n### Rewritten Activities\\n\\nThe following activities have been substantially rewritten with new data schemas. If you have existing analysis pipelines for these games, review the updated documentation.\\n\\n| Game | What Changed | Documentation |\\n|------|-------------|---------------|\\n| **Balloon Risk (BART)** | Rewritten with standard BART metrics. `avg_pumps_collected` is the primary risk-taking index (pumps on non-popped balloons only). `balloon_results` provides per-balloon pump counts and outcomes for learning-curve analysis. `breakpoints` echoes the hidden pop thresholds, enabling risk calibration analysis. The previous `static_data.points` field (total pumps from collected balloons) is now `total_earnings` (same value, same calculation). | [Balloon Risk docs](/activities/reference/balloon-risk) |\\n| **Scratch Card** | Rewritten with per-card results and structured data. `avg_scratch_time_ms` measures psychomotor speed. Per-card `scratch_path` (sampled pointer trajectory with timestamps) and scene element bounding boxes enable spatial analysis of visual attention and motor control. The previous version had minimal data output. | [Scratch Card docs](/activities/reference/scratch-card) |\\n\\n### Post-Game Questionnaire\\n\\nAll modernized games now include a brief post-game questionnaire with two ratings (instruction clarity and willingness to repeat, each on a 1-5 scale). This data appears in the `questionnaire` field within `static_data`. Participants will see two emoji-based rating screens after completing each game.\\n\\n### Bug Fixes\\n\\n| Game | Fix |\\n|------|-----|\\n| **Jewels A and B** | Selecting \\"No\\" on the continue prompt was incorrectly advancing to the next level instead of ending the game. Now correctly ends the session. |\\n| **Pop the Bubbles** | Score screen now displays after the final round before the questionnaire. Improved tap responsiveness on mobile devices. |\\n| **D-Cog** | Dog visibility increased from 1 to 2 seconds. No-response rounds are no longer counted as successes. Audio feedback replaced with subtle chimes. |\\n| **Symbol-Digit Substitution** | Fixed an issue where the previous guess button stayed highlighted in the next round. |\\n| **All games** | Post-game questionnaire emoji faces now display in consistent left-to-right order (sad to happy). |\\n\\n## What This Means for You\\n\\n**Researchers with active studies:** If you use Balloon Risk or Scratch Card, review the updated documentation as those data schemas have changed. For all other games, your existing analysis code will continue to work, since all legacy fields are preserved. New fields are available if you want richer data going forward.\\n\\n**Digital navigators and coordinators:** The participant experience for existing games is largely unchanged. The most noticeable difference is the post-game questionnaire (two quick ratings after each game). No action is needed on your part.\\n\\n**Participants:** Existing games look and feel the same. No action needed.\\n\\n## Reporting Issues\\n\\nIf you encounter any problems with the updated games, please email mindlamp@bidmc.harvard.edu.\\n\\n## Documentation\\n\\nAll activity documentation has been updated:\\n\\n- [Activity Reference](/activities/reference): complete list of all activities\\n- [Capabilities: Collect](/capabilities/collect): updated showcase with game icons and cognitive domains"},{"id":"welcome","metadata":{"permalink":"/blog/welcome","source":"@site/blog/2026-02-10-welcome.md","title":"Welcome to mindLAMP Updates!","description":"Welcome to mindLAMP Updates, where we\'ll keep research and clinical teams up to date on the platform.","date":"2026-02-10T00:00:00.000Z","tags":[{"inline":false,"label":"Announcements","permalink":"/blog/tags/announcements","description":"News and announcements about mindLAMP"}],"readingTime":0.32,"hasTruncateMarker":true,"authors":[{"name":"Eden Rozenblit","page":{"permalink":"/blog/authors/edenrozenblit"},"socials":{"linkedin":"https://www.linkedin.com/in/eden-rozenblit/","github":"https://github.com/e-rozenblit"},"imageURL":"https://avatars.githubusercontent.com/u/168096182?v=4","key":"edenrozenblit"}],"frontMatter":{"slug":"welcome","title":"Welcome to mindLAMP Updates!","authors":["edenrozenblit"],"tags":["announcements"]},"unlisted":false,"prevItem":{"title":"Activity Suite Update: Enriched Data Output and Bug Fixes","permalink":"/blog/activity-suite-update-april-2026"}},"content":"Welcome to mindLAMP Updates, where we\'ll keep research and clinical teams up to date on the platform.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What to Expect\\n\\nYou can expect:\\n\\n- **Platform Updates**: New features, improvements, and releases\\n- **Research Highlights**: Studies and publications using mindLAMP\\n- **Tutorials**: Step-by-step guides for researchers and developers\\n- **Community News**: Events, workshops, and collaboration opportunities\\n\\nNew posts will follow regularly."}]}}')}}]);